    var basis = fmtS(tr('ad.q.basisText')[scn], v); if (Math.abs(pitchM() - 0.3) > 1e-6) basis = basis.replace(/300 mm/g, Math.round(pitchM() * 1000) + ' mm').replace(/30 cm/g, nf(pitchM() * 100, 0) + ' cm');
